import cv2
import sys

img = cv2.imread(sys.argv[1], cv2.IMREAD_UNCHANGED)
if img is None:
    print("Error reading image")
else:
    print(f"Shape: {img.shape}")
    if len(img.shape) == 2:
        print("Grayscale")
    elif len(img.shape) == 3 and img.shape[2] == 3:
        # Check if all channels are equal (it might be saved as RGB but with gray values)
        b, g, r = cv2.split(img)
        if (b == g).all() and (b == r).all():
             print("Grayscale (saved as RGB)")
        else:
             print("RGB")

